const stageMap = {
  'Qualified': 'lead.qualified',
  'Booked': 'lead.booked',
  'Proposal Sent': 'proposal.ready',
  'Won': 'client.won'
};
const stage = $json.current_stage;
const event_type = stageMap[stage] || null;
return [{
  json: {
    event_type,
    client_id: $json.id,
    odoo_lead_id: $json.odoo_lead_id,
    detected_stage: stage,
    payload: { detected_stage: stage }
  }
}];
